	allegiance = "Desconhecida",
	aliases = { "o paladino tombado de Uldaman" },
	sections = {
		{
			title = "Resumo",
			text = [=[Num corredor do grande salão do templo de {link:uldaman}Uldaman{/link} jazem os restos de um paladino humano. Ele veio aos {link:badlands}Ermos{/link} numa missão escolhida por ele mesmo, para purgar uma mácula maligna que acreditava pairar sobre o sítio de escavação. Usava um belo colar mágico feito para ele por Talvash del Kissel, um joalheiro {link:gnomes}gnomo{/link} de {link:ironforge}Altaforja{/link}. Morreu no cofre, e seu colar foi quebrado e suas gemas espalhadas. Seu diário manchado de sangue, escrito na língua dos humanos, está a seu lado.]=],
		},
		{
			title = "Importância",
			text = [=[A morte do paladino projetou uma longa sombra. Um rival de Talvash espalhou que o colar amaldiçoara quem o usava, e o negócio do joalheiro foi arruinado. Na {link:horde}Horda{/link}, os recuperadores de Droffers e Filho também ouviram falar do colar, e o quiseram.]=],
		},
		{
			title = "Não Registrado",
			text = [=[Nenhum registro dá o nome do paladino, sua ordem ou seu lar. Que mácula maligna era aquela, e se ele a encontrou, não se sabe.]=],
		},
	},
	chapters = {
		{
			title = "O Diário do Paladino",
			hint = "Procure o paladino morto nos salões de Uldaman.",
			text = [=[O diário foi a última obra do paladino. Ele descobrira para onde cada gema tinha ido. Os anões Shadowforge haviam escondido o rubi em suas barricadas enquanto combatiam os troggs pelo cofre. Os troggs haviam posto o topázio numa urna perto de um acampamento de anões de {link:ironforge}Altaforja{/link}. O chefe {link:troggs}trogg{/link} ficara com a safira. Do lado da {link:horde}Horda{/link}, o diário não pôde ser lido até que o troll {link:jarkal-mossmeld}Jarkal Mossmeld{/link}, de {link:kargath}Karrath{/link}, o traduzisse, em troca da chance de ele mesmo estudar o colar.]=],
		},
	},
	mentions = {
